CREATE TABLE IF NOT EXISTS exchange_rate (id INT PRIMARY KEY, rate DECIMAL(10,4) NOT NULL, version INT NOT NULL DEFAULT 0, updated_at VARCHAR(30) NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS audit (id BIGINT AUTO_INCREMENT PRIMARY KEY, entity VARCHAR(40) NOT NULL, entity_id VARCHAR(80) NOT NULL, before_data LONGTEXT, after_data LONGTEXT NOT NULL, created_at VARCHAR(30) NOT NULL, actor_username VARCHAR(100) NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS sessions (token_hash CHAR(64) PRIMARY KEY, expires_at BIGINT NOT NULL, username VARCHAR(100) NULL, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attempts (bucket_key CHAR(64) PRIMARY KEY, attempts INT NOT NULL, expires_at BIGINT NOT NULL, INDEX(expires_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS product_overrides (id INT PRIMARY KEY, data LONGTEXT NOT NULL, version INT NOT NULL) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS requests (reference VARCHAR(40) PRIMARY KEY, idempotency_key CHAR(64) UNIQUE NOT NULL, body_hash CHAR(64) NOT NULL, data LONGTEXT NOT NULL, summary LONGTEXT NOT NULL, version INT NOT NULL DEFAULT 0, created_at VARCHAR(30) NOT NULL, INDEX(created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS request_files (id CHAR(32) PRIMARY KEY, reference VARCHAR(40) NOT NULL, name VARCHAR(200) NOT NULL, size INT NOT NULL, sha256 CHAR(64) NOT NULL, FOREIGN KEY(reference) REFERENCES requests(reference) ON DELETE CASCADE) ENGINE=InnoDB;
